function linkRightNeighbours(root: TreeNode | null): number[][] {
  if (!root) return [];
  let level: TreeNode[] = [root];
  while (level.length) {
    const next: TreeNode[] = [];
    level.forEach((node, i) => {
      (node as any).next = i + 1 < level.length ? level[i + 1] : null;
      if (node.left) next.push(node.left);
      if (node.right) next.push(node.right);
    });
    level = next;
  }
  // read the rows back through the next pointers
  const rows: number[][] = [];
  for (let first: TreeNode | null = root; first; first = first.left) {
    const row: number[] = [];
    for (let cur: any = first; cur; cur = cur.next) row.push(cur.val);
    rows.push(row);
  }
  return rows;
}

