class Solution:
    def linkRightNeighbours(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        level = [root]
        while level:
            for i, node in enumerate(level):
                node.next = level[i + 1] if i + 1 < len(level) else None
            level = [c for node in level for c in (node.left, node.right) if c]
        # read the rows back through the next pointers
        rows, first = [], root
        while first:
            row, cur = [], first
            while cur:
                row.append(cur.val)
                cur = cur.next
            rows.append(row)
            first = first.left
        return rows

